JOIN trade_records tr ON rc."REC_COMP" = tr."REC_KEY"
WHERE rc."invest_stat" = 'Preliminary';

SELECT DISTINCT rc."case_flag", rc."invest_stat", rc."alert_lvl"
FROM reg_compliance rc
LIMIT 10;

SELECT COUNT(*) FROM reg_compliance rc 
JOIN trade_records tr ON rc."REC_COMP" = tr."REC_KEY"
WHERE CAST(rc."compliance_data"->>'risk_val' AS numeric) > 50;

SELECT COUNT(*) FROM reg_compliance rc 
JOIN trade_records tr ON rc."REC_COMP" = tr."REC_KEY"
